UPDATE public.exam_tactics SET breakdown = $tagbd${"intro": "[[q]]during[[/q]] ardından her zaman bir İSİM/isim öbeği, [[q]]while[[/q]] ardından ise ÖZNE+YÜKLEM içeren tam bir CÜMLECİK gelir — ikisi de [[b]]\"...sırasında/esnasında\"[[/b]] anlamı taşısa da yapısal olarak kesinlikle birbirinin yerine geçmez:", "items": [{"heading": "during + İsim / İsim Öbeği", "badge": "Yapısal Kural", "body": [{"type": "text", "text": "[[q]]during[[/q]] ardından her zaman bir İSİM ya da isim öbeği gelir: [[q]]\"during the meeting\"[[/q]], [[q]]\"during the summer\"[[/q]], [[q]]\"during his speech\"[[/q]]."}, {"type": "example_check", "correct": "during the meeting", "wrong_note": "\"during he was speaking\" gramer hatasıdır, çünkü during'den sonra özne+yüklem gelemez"}]}, {"heading": "while + Özne + Yüklem", "badge": "Yapısal Kural", "body": [{"type": "text", "text": "[[q]]while[[/q]] ardından ise ÖZNE + YÜKLEM içeren TAM BİR CÜMLECİK gelir: [[q]]\"while he was speaking\"[[/q]], [[q]]\"while I was cooking\"[[/q]]."}, {"type": "example_check", "correct": "while he was speaking", "wrong_note": "\"while the meeting\" gramer hatasıdır, çünkü while'dan sonra isim öbeği gelemez"}]}, {"heading": "during / for Tuzağı", "badge": "Sık Karıştırılır", "body": [{"type": "text", "text": "[[amber]]\"for\"[[/amber]] bir sürenin [[dark]]UZUNLUĞUNU[[/dark]] verir ([[q]]\"for two hours\"[[/q]]), [[amber]]\"during\"[[/amber]] ise bir zaman [[dark]]DİLİMİNİN İÇİNDE[[/dark]] gerçekleştiğini belirtir ([[q]]\"during the two-hour meeting\"[[/q]]). Sınavda boşluktan HEMEN SONRASINA bakmadan sadece anlama güvenmek bu ayrımda yanlış şıkkı seçtirir."}]}], "examples": [{"sentence": "She fell asleep during the long, boring lecture on economic history.", "answer_word": "during", "reasoning": "Boşluktan sonra bir isim öbeği ([[q]]\"the long, boring lecture\"[[/q]]) geldiği için doğru cevap [[right]]\"during\"[[/right]]dir; [[wrong]]\"while\"[[/wrong]] burada özne+yüklem gerektirdiği için yanlıştır."}, {"sentence": "The lights suddenly went out while we were watching the final scene of the movie.", "answer_word": "while", "reasoning": "Boşluktan sonra özne+yüklem içeren tam bir cümlecik ([[q]]\"we were watching...\"[[/q]]) geldiği için doğru cevap [[right]]\"while\"[[/right]]dır; [[wrong]]\"during\"[[/wrong]] burada bir isim öbeği gerektirdiği için yanlıştır."}, {"sentence": "He kept nervously checking his phone during the entire presentation, which visibly annoyed the speaker.", "answer_word": "during", "reasoning": "Boşluktan sonra bir isim öbeği ([[q]]\"the entire presentation\"[[/q]]) geldiği için doğru cevap [[right]]\"during\"[[/right]]dir; [[wrong]]\"while\"[[/wrong]] burada özne+yüklem içeren bir cümlecik gerektirdiği için yanlıştır."}, {"sentence": "While she was driving to work this morning, she suddenly remembered that she had left the oven on at home.", "answer_word": "While", "reasoning": "Boşluktan sonra özne+yüklem içeren tam bir cümlecik ([[q]]\"she was driving...\"[[/q]]) geldiği için doğru cevap [[right]]\"While\"[[/right]]dır; [[wrong]]\"during\"[[/wrong]] burada bir isim öbeği gerektirdiği için kullanılamaz."}]}$tagbd$::jsonb WHERE id = 'f7de751d-c537-424b-89f6-da2086e3f3fe';
UPDATE public.exam_tactics SET breakdown = $tagbd${"intro": "[[q]]going to[[/q]] önceden PLANLANMIŞ bir niyeti ya da somut bir KANITA dayalı tahmini anlatır; [[q]]will[[/q]] ise o anda alınan SPONTANE bir kararı, bir SÖZ/TEKLİF'i ya da kişisel bir GÖRÜŞE dayalı tahmini anlatır:", "items": [{"heading": "going to Kullanılır", "badge": "Önceden Planlanmış / Kanıta Dayalı", "body": [{"type": "text", "text": "Cümlede bir eylemin konuşmadan [[dark]]ÖNCE[[/dark]] planlandığına dair bir ipucu varsa ([[q]]\"I have already decided\"[[/q]], [[q]]\"We have booked...\"[[/q]]), [[ok]]going to[[/ok]] kullanılır."}, {"type": "text", "text": "Gözle görülür bir [[amber]]KANIT[[/amber]] varsa (ör. [[q]]\"Look at those clouds\"[[/q]] gibi somut bir işaret), yine [[ok]]going to[[/ok]] ile tahmin yapılır ([[q]]\"It's going to rain\"[[/q]])."}, {"type": "example_check", "correct": "We are going to rent a car", "wrong_note": "\"will rent\" burada o anda verilen bir karar izlenimi yaratır ve önceden planlanmış olmasıyla çelişir"}]}, {"heading": "will Kullanılır", "badge": "Anlık Karar / Söz / Kişisel Görüş", "body": [{"type": "text", "text": "Konuşma [[dark]]ANINDA[[/dark]], o an alınan SPONTANE bir karar varsa ([[q]]\"The phone is ringing, I'll answer it\"[[/q]]) veya bir SÖZ/TEKLİF/RİCA söz konusuysa ([[q]]\"I'll help you\"[[/q]], [[q]]\"Will you marry me?\"[[/q]]), [[ok]]will[[/ok]] kullanılır."}, {"type": "text", "text": "[[amber]]\"I think/believe/suppose\"[[/amber]] gibi KİŞİSEL GÖRÜŞE dayalı bir tahmin yapılıyorsa (somut kanıt değil, fikir), yine [[ok]]will[[/ok]] tercih edilir ([[q]]\"I think it will rain tomorrow\"[[/q]])."}]}], "examples": [{"sentence": "Look out! That glass is right at the edge of the table — it is going to fall!", "answer_word": "is going to fall", "reasoning": "Konuşan kişi o an GÖRDÜĞÜ somut bir kanıta (bardağın kenarda olması) dayanarak tahmin yapıyor → doğru cevap [[right]]\"is going to fall\"[[/right]]dir."}, {"sentence": "I'm not sure about the weather, but I think it will be sunny this weekend.", "answer_word": "will be", "reasoning": "Burada somut bir kanıt değil, kişisel bir GÖRÜŞ/TAHMİN ([[q]]\"I think\"[[/q]]) söz konusu → doğru cevap [[right]]\"will be\"[[/right]]dir; [[wrong]]\"is going to be\"[[/wrong]] burada daha az doğaldır çünkü gözle görülür bir kanıttan değil, fikirden bahsediliyor."}, {"sentence": "We've already decided — we are going to rent a car for the whole trip instead of relying on public transport.", "answer_word": "are going to rent", "reasoning": "\"already decided\" ifadesi eylemin konuşmadan ÖNCE planlandığını gösteriyor → doğru cevap [[right]]\"are going to rent\"[[/right]]tir; [[wrong]]\"will rent\"[[/wrong]] burada o anda verilen bir karar izlenimi yaratır ve \"already decided\" ile çelişir."}, {"sentence": "Can someone answer the door? — Sure, I will get it.", "answer_word": "will get", "reasoning": "Bu, konuşma ANINDA alınan SPONTANE bir karar/teklif olduğu için doğru cevap [[right]]\"will get\"[[/right]]tir; [[wrong]]\"am going to get\"[[/wrong]] burada önceden kurulmuş bir plan izlenimi verir ki bu, anlık bir teklife uymaz."}]}$tagbd$::jsonb WHERE id = '2725b7bc-7144-4958-a14d-5552d3ed7760';
UPDATE public.exam_tactics SET breakdown = $tagbd${"intro": "[[q]]have been to[[/q]] bir yere GİTMİŞ ve GERİ DÖNMÜŞ olmayı, yani bir deneyimi anlatır; [[q]]have gone to[[/q]] ise özne o yere gitmiş ve [[dark]]HÂLÂ ORADA[[/dark]] ya da yolda olup henüz dönmemiş demektir:", "items": [{"heading": "been to: Deneyim Anlatır", "badge": "Dönmüş", "body": [{"type": "text", "text": "[[q]]have been to[[/q]] genellikle [[amber]]\"ever, never, three times\"[[/amber]] gibi DENEYİM belirteçleriyle birlikte görülür: [[q]]\"I have been to Japan three times.\"[[/q]]"}]}, {"heading": "gone to: Hâlâ Orada / Yolda", "badge": "Dönmemiş", "body": [{"type": "text", "text": "[[q]]have gone to[[/q]] özne o yere gitmiş ve [[dark]]HÂLÂ ORADA[[/dark]] ya da yolda olup henüz dönmemiş demektir — bu yüzden konuşan kişi ([[q]]\"I\"[[/q]]) için mantıksal olarak [[q]]\"I have gone to...\"[[/q]] neredeyse hiç kullanılmaz, çünkü konuşuyorsa zaten dönmüştür ya da oradadır."}, {"type": "text", "text": "Bu kalıp neredeyse her zaman [[amber]]ÜÇÜNCÜ TEKİL/ÇOĞUL ŞAHISLARLA[[/amber]] kullanılır: [[q]]\"She has gone to the supermarket\"[[/q]] (şu an orada, henüz dönmedi)."}]}, {"heading": "been / gone Karıştırılması", "is_warning": true, "warning_label": "🔥 EN SIK TUZAK", "body": [{"type": "text", "text": "Sınavda cümlede kişinin HÂLÂ YOK olduğunu gösteren bir ipucu ([[q]]\"she'll be back soon\"[[/q]], [[q]]\"he's not here right now\"[[/q]]) varsa [[dark]]gone[[/dark]] doğrudur; sayı/deneyim belirteci ([[q]]\"three times\"[[/q]], [[q]]\"ever\"[[/q]]) varsa [[dark]]been[[/dark]] doğrudur."}], "meaning_pairs": [[{"word": "been to", "meaning": "gitmiş ve GERİ DÖNMÜŞ (deneyim)"}, {"word": "gone to", "meaning": "hâlâ orada / yolda, HENÜZ DÖNMEMİŞ", "variant": "wrong"}]], "warning_text": "İkisi de benzer göründüğü için, cümledeki \"hâlâ orada mı\" yoksa \"dönmüş mü\" ipucunu kaçırmak bu sorularda en sık yapılan hatadır."}], "examples": [{"sentence": "Where's Mary? She has gone to the supermarket; she'll be back in ten minutes.", "answer_word": "has gone", "reasoning": "Cümledeki [[q]]\"she'll be back\"[[/q]] ifadesi Mary'nin ŞU AN orada/yolda olduğunu, henüz dönmediğini gösteriyor → doğru cevap [[right]]\"has gone\"[[/right]]dur."}, {"sentence": "I have been to Japan three times, and I loved every single trip.", "answer_word": "have been", "reasoning": "Burada [[q]]\"three times\"[[/q]] bir deneyim sayacı ve konuşan kişi (I) şu an konuştuğuna göre zaten geri dönmüş → doğru cevap [[right]]\"have been\"[[/right]]dir; [[wrong]]\"have gone\"[[/wrong]] burada anlamsız olurdu."}, {"sentence": "By the time we arrived at her house, she had gone to the dentist, so we had to wait nearly an hour for her to come back.", "answer_word": "had gone", "reasoning": "Cümledeki [[q]]\"we had to wait... for her to come back\"[[/q]] ifadesi kadının HÂLÂ GERİ DÖNMEMİŞ olduğunu gösteriyor → doğru cevap [[right]]\"had gone\"[[/right]]dur (gone'un geçmiş zaman hali); [[wrong]]\"had been\"[[/wrong]] burada yanlıştır çünkü \"been\" dönmüş olmayı ima eder, oysa burada kişi hâlâ yoktur."}, {"sentence": "Have you ever been to Egypt? I've heard the pyramids are absolutely breathtaking.", "answer_word": "been", "reasoning": "Cümledeki [[q]]\"ever\"[[/q]] bir DENEYİM belirtecidir ve soruyu soran kişi karşısındakinin şu an burada olduğunu (yani gitmişse dönmüş olduğunu) varsayar → doğru cevap [[right]]\"been\"[[/right]]dir; [[wrong]]\"gone\"[[/wrong]] burada kullanılsaydı kişinin hâlâ Mısır'da olduğu gibi anlamsız bir çıkarım yapılırdı."}]}$tagbd$::jsonb WHERE id = '0c988772-ece0-4cc1-958a-f6dfaa659964';
UPDATE public.exam_tactics SET breakdown = $tagbd${"intro": "[[q]]each[[/q]] bir gruptaki üyeleri TEK TEK ele alır ve iki üyeli bir grupla bile kullanılabilir; [[q]]every[[/q]] ise bir grubu BÜTÜN olarak genellemek için kullanılır ve EN AZ ÜÇ üyeli bir grup gerektirir:", "items": [{"heading": "each: Teker Teker, İki Üyeyle Bile Kullanılır", "badge": "Birey Birey", "body": [{"type": "text", "text": "[[q]]each[[/q]] bir gruptaki üyeleri TEK TEK, birey birey ele alır ve İKİ üyeli bir grupla bile kullanılabilir: [[q]]\"each of the two candidates\"[[/q]]. [[amber]]each[[/amber]] isimsiz, tek başına da kullanılabilir ([[q]]\"Each has its own strengths\"[[/q]]) ve sıkça [[q]]\"each of + the/my/these\"[[/q]] kalıbıyla görülür."}]}, {"heading": "every: Toptan, En Az Üç Üye Gerektirir", "badge": "Topluca", "body": [{"type": "text", "text": "[[q]]every[[/q]] bir grubu BÜTÜN olarak genellemek için kullanılır ve EN AZ ÜÇ üyeli bir grup gerektirir — ikili bir grupla [[bad]]every[[/bad]] kullanılmaz."}, {"type": "text", "text": "[[q]]every[[/q]] ASLA isimsiz ya da \"of\" ile kullanılmaz ([[bad]]\"every of the students\"[[/bad]] KESİNLİKLE YANLIŞTIR), doğrudan tekil bir isimle birleşir ([[q]]\"every student\"[[/q]]). Ayrıca sıklık ifadelerinde de kullanılır ([[q]]\"every two hours\"[[/q]], [[q]]\"every other day\"[[/q]]) — bu kullanımda [[amber]]each[[/amber]] tercih edilmez."}]}, {"heading": "Sınav İpucu: \"of the two\" Görürsen", "badge": "Hızlı Eleme", "body": [{"type": "text", "text": "Sınavda boşluktan sonra [[q]]\"of the two...\"[[/q]] gibi İKİLİ bir grup görürsen [[bad]]every[[/bad]] otomatik olarak elenir."}]}], "examples": [{"sentence": "Each of the two finalists gave an impressive speech, but only one of them could win the prize.", "answer_word": "Each", "reasoning": "Burada sadece İKİ finalistten bahsediliyor ve [[bad]]every[[/bad]] en az üç üye gerektirdiği için elenir → doğru cevap [[right]]\"Each\"[[/right]]tir."}, {"sentence": "Every student in the department must submit the application form by Friday, with no exceptions.", "answer_word": "Every", "reasoning": "Burada genel bir kural TÜM bölüm öğrencilerine (üç veya daha fazla kişiye) uygulanıyor → doğru cevap [[right]]\"Every\"[[/right]]dir; [[wrong]]\"Each\"[[/wrong]] de gramatik olarak mümkün olsa da [[q]]\"no exceptions\"[[/q]] ifadesiyle kurulan kesin genelleme tonu \"every\"yi daha doğru kılar."}, {"sentence": "Each of the two candidates has strengths that the other clearly lacks, which makes the decision difficult.", "answer_word": "Each", "reasoning": "Burada sadece İKİ adaydan bahsedildiği için, en az üç üye gerektiren [[bad]]every[[/bad]] elenir → doğru cevap [[right]]\"Each\"[[/right]]tir."}, {"sentence": "Every employee in the department is required to complete the online safety course once a year, with no exceptions.", "answer_word": "Every", "reasoning": "Burada genel bir kural bölümdeki TÜM çalışanlara (üçten fazla kişiye) toptan uygulanıyor → doğru cevap [[right]]\"Every\"[[/right]]dir; cümledeki [[q]]\"with no exceptions\"[[/q]] ifadesi de bu toptan genellemeyi pekiştirir."}]}$tagbd$::jsonb WHERE id = '81d9ef24-7274-4259-8f54-3f2c763254e8';
UPDATE public.exam_tactics SET breakdown = $tagbd${"intro": "Boşluktan sonra ya da önce bir İSİM varsa cevap sıfat olan [[q]]good[[/q]]tur; boşluk bir FİİLİ nitelendiriyorsa cevap zarf olan [[q]]well[[/q]]dir — ama [[dark]]\"well\"[[/dark]]'ün SAĞLIK anlamında istisnai bir sıfat kullanımı da vardır:", "items": [{"heading": "good: İsmi Niteleyen Sıfat", "badge": "İsim + good", "body": [{"type": "text", "text": "Boşluktan sonra ya da önce bir İSİM varsa ve o ismin niteliğinden bahsediliyorsa ([[q]]\"a good book\"[[/q]], [[q]]\"the food was good\"[[/q]]) cevap sıfat olan [[ok]]good[[/ok]]tur."}]}, {"heading": "well: Fiili Niteleyen Zarf", "badge": "Fiil + well", "body": [{"type": "text", "text": "Boşluk bir FİİLİ nitelendiriyorsa ([[q]]\"she sings well\"[[/q]], [[q]]\"he did well on the exam\"[[/q]]) cevap zarf olan [[ok]]well[[/ok]]dir."}, {"type": "example_check", "correct": "She sings well", "wrong_note": "\"good\" bir fiili asla niteleyemez"}]}, {"heading": "İstisna: well Sağlık Anlamında Sıfat Olur", "badge": "YDS Tuzağı", "body": [{"type": "text", "text": "YDS'nin sık kullandığı tuzak, [[q]]\"be\"[[/q]] fiiliyle kurulan cümlelerde ortaya çıkar: [[amber]]\"feel, look, seem, be\"[[/amber]] gibi bağlantı (linking) fiillerinden sonra normalde sıfat beklenir, ama [[dark]]\"well\"[[/dark]] istisnai olarak bu konumda SAĞLIK durumunu anlatan bir SIFAT olarak da kullanılabilir ([[q]]\"I don't feel well\"[[/q]] = kendimi iyi hissetmiyorum, hasta gibi)."}, {"type": "text", "text": "Yani [[b]]\"well\"[[/b]] gördüğünde önce cümlenin sağlıkla mı ilgili olduğuna, değilse hangi kelimeyi (isim mi fiil mi) nitelediğine bak."}]}], "examples": [{"sentence": "He performed so well in the final interview that they offered him the position immediately.", "answer_word": "well", "reasoning": "Boşluk [[q]]\"performed\"[[/q]] (fiil) eylemini nitelediği için doğru cevap zarf olan [[right]]\"well\"[[/right]]dir; [[wrong]]\"good\"[[/wrong]] bir fiili asla niteleyemez."}, {"sentence": "My grandmother hasn't been feeling well lately, so she's seeing a doctor tomorrow.", "answer_word": "well", "reasoning": "Burada [[q]]\"feel\"[[/q]] bağlantı fiilinden sonra sağlık durumu anlatıldığı için istisnai olarak [[right]]\"well\"[[/right]] (sıfat, 'iyi/sağlıklı' anlamında) doğru cevaptır; [[wrong]]\"good\"[[/wrong]] burada genel bir ruh hali anlatır ama hastalık/sağlık bağlamında tercih edilen kelime \"well\"dir."}, {"sentence": "Despite the heavy rain, the charity event turned out to be a good success.", "answer_word": "good", "reasoning": "Boşluk [[q]]\"success\"[[/q]] (isim) kelimesini nitelediği için doğru cevap sıfat olan [[right]]\"good\"[[/right]]tur; [[wrong]]\"well\"[[/wrong]] bir ismi niteleyemez, sadece istisnai sağlık anlamında sıfat olarak kullanılabilir ki burada sağlıkla ilgili bir bağlam yoktur."}, {"sentence": "The negotiations went so well that both sides signed the agreement a day early.", "answer_word": "well", "reasoning": "Boşluk [[q]]\"went\"[[/q]] fiilini nitelediği için doğru cevap zarf olan [[right]]\"well\"[[/right]]dir; [[wrong]]\"good\"[[/wrong]] bir fiili nitelendiremeyeceği için yanlıştır."}]}$tagbd$::jsonb WHERE id = '4fb315b2-b67f-46ec-a1f7-7cfbb510c876';
UPDATE public.exam_tactics SET breakdown = $tagbd${"intro": "Cümlede bir UYARI / kötü sonuç ima ediliyorsa [[q]]had better + V1[[/q]], iki seçenek arasında bir TERCİH anlatılıyorsa [[q]]would rather + V1[[/q]] (başkasının eylemiyle ilgiliyse [[q]]would rather + özne + past simple[[/q]]) kullanılır:", "items": [{"heading": "had better + V1: Uyarı", "badge": "Kötü Sonuç Uyarısı", "body": [{"type": "text", "text": "Cümlede bir UYARI ya da yapılmazsa KÖTÜ BİR SONUÇ doğacağı hissi varsa (genellikle [[q]]\"or\"[[/q]], [[q]]\"otherwise\"[[/q]] ile devam eder) doğru yapı [[q]]\"had better + V1\"[[/q]]dir ([[q]]\"You'd better hurry, or you'll miss the train\"[[/q]])."}]}, {"heading": "would rather + V1: Kendi Tercihi", "badge": "Tercih", "body": [{"type": "text", "text": "Cümle iki seçenek arasında bir TERCİHİ anlatıyorsa ([[q]]\"X yapmak yerine Y yapmayı tercih ederim\"[[/q]]) doğru yapı [[q]]\"would rather + V1\"[[/q]]dir."}]}, {"heading": "would rather + Özne + Past Simple: Başkasının Eylemi", "badge": "YDS Tuzağı", "body": [{"type": "text", "text": "Eğer tercih BAŞKA BİR KİŞİNİN eylemiyle ilgiliyse [[q]]\"would rather + özne + past simple\"[[/q]] kullanılır ([[q]]\"I'd rather you left now\"[[/q]] — şu an için bile geçmiş zaman formu kullanılır, bu YDS'nin klasik tuzağıdır)."}]}, {"heading": "'to' KULLANILMAZ", "badge": "Ortak Kural", "body": [{"type": "text", "text": "Her iki yapıdan sonra da [[bad]]\"to\"[[/bad]] KULLANILMAZ: [[bad]]\"had better to go\"[[/bad]] ya da [[bad]]\"would rather to go\"[[/bad]] kesinlikle yanlıştır."}]}], "examples": [{"sentence": "You had better finish the report today, or the client will cancel the contract.", "answer_word": "had better", "reasoning": "Cümlede açık bir UYARI ve olumsuz sonuç ([[q]]\"or the client will cancel\"[[/q]]) olduğu için doğru cevap [[right]]\"had better\"[[/right]]dır; [[wrong]]\"would rather\"[[/wrong]] burada bir tercih değil bir zorunluluk/uyarı anlatıldığı için uygun değildir."}, {"sentence": "I'd rather you didn't talk about this to anyone else for now.", "answer_word": "didn't talk", "reasoning": "Tercih BAŞKA bir kişinin (you) eylemiyle ilgili olduğu için fiil past simple formunda gelir → doğru cevap [[right]]\"didn't talk\"[[/right]]tur; [[wrong]]\"don't talk\"[[/wrong]] ya da [[wrong]]\"won't talk\"[[/wrong]] bu yapıda kullanılmaz."}, {"sentence": "You had better lock the office tonight, or the night guard will report the breach to management.", "answer_word": "had better", "reasoning": "Cümlede açık bir UYARI ve olumsuz sonuç ([[q]]\"or the night guard will report\"[[/q]]) bulunduğu için doğru cevap [[right]]\"had better\"[[/right]]dır; [[wrong]]\"would rather\"[[/wrong]] burada bir tercih değil bir zorunluluk anlattığı için uygun değildir."}, {"sentence": "I'd rather my sister told the truth before everyone found out from someone else.", "answer_word": "told", "reasoning": "Tercih BAŞKA bir kişinin (my sister) eylemiyle ilgili olduğu için fiil past simple formunda gelir → doğru cevap [[right]]\"told\"[[/right]]dur; [[wrong]]\"tell\"[[/wrong]] ya da [[wrong]]\"will tell\"[[/wrong]] bu yapıda kullanılmaz."}]}$tagbd$::jsonb WHERE id = '611cc281-bc26-43a8-8662-fb013072fb6e';
UPDATE public.exam_tactics SET breakdown = $tagbd${"intro": "Bir -ing formu cümlede ÖZNE ya da NESNE konumundaysa bu bir [[q]]gerund[[/q]]'dur ve isim gibi davranır; bazı fiiller ve tüm edatlardan sonra da kesinlikle gerund gelir:", "items": [{"heading": "Özne veya Nesne Konumunda -ing = Gerund", "badge": "Temel Kural", "body": [{"type": "text", "text": "Bir -ing formu cümlede ÖZNE konumunda (cümlenin başında, tekil fiil alarak) veya fiilin NESNESİ konumunda ise, bu bir gerund'dur ve isim gibi davranır: [[q]]\"Smoking is bad for your health\"[[/q]] (özne), [[q]]\"I enjoy reading\"[[/q]] (nesne)."}]}, {"heading": "Sadece Gerund Alan Fiiller", "badge": "Ezbere Bilinmeli", "body": [{"type": "text", "text": "[[amber]]enjoy, avoid, mind, suggest, finish, admit, deny, practice[[/amber]] gibi bazı fiiller kesinlikle sadece gerund alır, asla to-infinitive almaz — boşluktan önce bu fiillerden biri varsa [[bad]]\"to + fiil\"[[/bad]] şıkkı doğrudan elenir."}]}, {"heading": "Edattan Sonra Her Zaman -ing", "badge": "Edat Kuralı", "body": [{"type": "text", "text": "Bir edattan ([[amber]]in, by, without, after, before[[/amber]]) sonra gelen fiil de her zaman -ing formundadır, çünkü edatlardan sonra isim soylu bir yapı gelir."}]}], "examples": [{"sentence": "Learning a new language requires patience and daily practice.", "answer_word": "Learning", "reasoning": "Cümlenin öznesi olan ve tekil fiil ([[q]]\"requires\"[[/q]]) alan bir -ing yapısı gerekir → doğru cevap [[right]]\"Learning\"[[/right]]dir."}, {"sentence": "She admitted signing the documents without her manager's approval.", "answer_word": "signing", "reasoning": "[[q]]\"admit\"[[/q]] fiilinden sonra kesinlikle gerund gelir, to-infinitive gelemez → doğru cevap [[right]]\"signing\"[[/right]]dir, [[wrong]]\"to sign\"[[/wrong]] seçeneği bu kuralı ihlal ettiği için elenir."}, {"sentence": "He always tries to avoid talking about his personal life during job interviews.", "answer_word": "talking", "reasoning": "[[q]]\"avoid\"[[/q]] fiilinden sonra kesinlikle gerund gelir, to-infinitive asla gelmez → doğru cevap [[right]]\"talking\"[[/right]]dir."}, {"sentence": "Practicing the piano for several hours every day eventually paid off when she won the national competition.", "answer_word": "Practicing", "reasoning": "Cümlenin öznesi konumunda bir -ing yapısı gerekir ve gerund öbeği her zaman tekil kabul edilir → doğru cevap [[right]]\"Practicing\"[[/right]]dir."}]}$tagbd$::jsonb WHERE id = 'c205e679-9ba6-4838-9fb8-3679b708acb3';
UPDATE public.exam_tactics SET breakdown = $tagbd${"intro": "Boşluktan hemen sonraki ifadenin TÜRÜNE bak: bir SÜRE ifadesi geliyorsa cevap [[q]]for[[/q]]dur; bir BAŞLANGIÇ NOKTASI geliyorsa cevap [[q]]since[[/q]]tir:", "items": [{"heading": "for + SÜRE İfadesi", "badge": "Süre", "body": [{"type": "text", "text": "Boşluktan hemen sonraki ifade bir SÜRE ifadesiyse ([[amber]]three years, two weeks, a long time, ages[[/amber]]) cevap [[ok]]for[[/ok]]dur."}]}, {"heading": "since + BAŞLANGIÇ NOKTASI", "badge": "Başlangıç Noktası", "body": [{"type": "text", "text": "Boşluktan hemen sonraki ifade bir BAŞLANGIÇ NOKTASIYSA ([[amber]]1998, last Monday, she graduated, childhood[[/amber]]) cevap [[ok]]since[[/ok]]tir. [[q]]since[[/q]] her zaman present perfect ([[q]]have/has + V3[[/q]]) ile kullanılır, çünkü o noktadan bugüne kadar süren bir durumu anlatır."}]}, {"heading": "for Zamanı Tek Başına Belirlemez", "badge": "Dikkat", "body": [{"type": "text", "text": "[[q]]for[[/q]] ise present perfect, past simple veya present perfect continuous ile de gelebilir, bu yüzden tek başına zamanı belirlemez — asıl ayraç her zaman kendisinden SONRA gelen ifadenin süre mi nokta mı olduğudur. [[q]]\"How long\"[[/q]] sorusu bu iki yapıyı tetikleyen klasik soru kalıbıdır ve cevapta mutlaka for/since'den biri beklenir."}]}], "examples": [{"sentence": "She has been working at this hospital since she finished medical school.", "answer_word": "since", "reasoning": "Boşluktan sonra [[q]]\"she finished medical school\"[[/q]] bir BAŞLANGIÇ NOKTASI (olay) olduğu için doğru cevap [[right]]\"since\"[[/right]]tir; [[wrong]]\"for\"[[/wrong]] gelseydi ardından [[q]]\"ten years\"[[/q]] gibi bir süre ifadesi gerekirdi."}, {"sentence": "They haven't seen each other for almost a decade.", "answer_word": "for", "reasoning": "Boşluktan sonra [[q]]\"almost a decade\"[[/q]] bir SÜRE ifadesi olduğu için doğru cevap [[right]]\"for\"[[/right]]dur; [[wrong]]\"since\"[[/wrong]] kullanılsaydı [[q]]\"2014\"[[/q]] gibi bir başlangıç noktası gerekirdi, bir süre ifadesiyle asla kullanılmaz."}, {"sentence": "He has lived in this neighborhood since he was a small child.", "answer_word": "since", "reasoning": "Boşluktan sonra [[q]]\"he was a small child\"[[/q]] bir BAŞLANGIÇ NOKTASI olduğu için doğru cevap [[right]]\"since\"[[/right]]tir; [[wrong]]\"for\"[[/wrong]] gelseydi ardından [[q]]\"many years\"[[/q]] gibi bir süre ifadesi gerekirdi."}, {"sentence": "The two companies have been negotiating this merger for over eighteen months now.", "answer_word": "for", "reasoning": "Boşluktan sonra [[q]]\"over eighteen months\"[[/q]] açık bir SÜRE ifadesi olduğu için doğru cevap [[right]]\"for\"[[/right]]dur; [[wrong]]\"since\"[[/wrong]] kullanılsaydı [[q]]\"early last year\"[[/q]] gibi bir başlangıç noktası gerekirdi, bir süre miktarıyla asla kullanılmaz."}]}$tagbd$::jsonb WHERE id = 'a3b441b0-06b5-49cc-a0b9-f7e2dd8cc3be';
